{"sql": "SELECT ms.molregno, ms.synonyms, ms.syn_type, ms.res_stem_id
FROM `bigquery-public-data.ebi_chembl.molecule_synonyms_23` ms
WHERE ms.syn_type = 'TRADE_NAME' AND ms.res_stem_id IN (
    SELECT res_stem_id FROM `bigquery-public-data.ebi_chembl.research_companies_23` WHERE company = 'SanofiAventis'
)
LIMIT 20"}

{"sql": "SELECT * FROM `bigquery-public-data.ebi_chembl.molecule_dictionary_23` WHERE molregno IN (
    SELECT DISTINCT ms.molregno 
    FROM `bigquery-public-data.ebi_chembl.molecule_synonyms_23` ms
    WHERE ms.res_stem_id IN (
        SELECT res_stem_id FROM `bigquery-public-data.ebi_chembl.research_companies_23` WHERE company = 'SanofiAventis'
    )
) LIMIT 10"}

{"sql": "SELECT DISTINCT ms.syn_type 
FROM `bigquery-public-data.ebi_chembl.molecule_synonyms_23` ms
WHERE ms.molregno IN (
    SELECT DISTINCT ms2.molregno 
    FROM `bigquery-public-data.ebi_chembl.molecule_synonyms_23` ms2
    WHERE ms2.res_stem_id IN (
        SELECT res_stem_id FROM `bigquery-public-data.ebi_chembl.research_companies_23` WHERE company = 'SanofiAventis'
    )
)
LIMIT 20"}

{"sql": "WITH sanofi_molecules AS (
    SELECT DISTINCT ms.molregno
    FROM `bigquery-public-data.ebi_chembl.molecule_synonyms_23` ms
    WHERE ms.res_stem_id IN (
        SELECT res_stem_id FROM `bigquery-public-data.ebi_chembl.research_companies_23` WHERE company = 'SanofiAventis'
    )
)
SELECT COUNT(*) as total_molecules FROM sanofi_molecules"}
